const express = require('express');
const multer = require('multer');
const dicomParser = require('dicom-parser');
const sharp = require('sharp');
const { GPU } = require('node-gpu');
const axios = require('axios');
const cors = require('cors');
const bodyParser = require('body-parser');
const mime = require('mime-types');
const { performance } = require('perf_hooks');
const { createLogger, format, transports } = require('winston');
const DailyRotateFile = require('winston-daily-rotate-file');

// Configurações de GPU (verificar suporte)
const gpu = new GPU();
if (!gpu.isAvailable()) {
  throw new Error('GPU não suportada ou não disponível');
}

// Configurações de armazenamento temporário
const upload = multer({ dest: 'temp_uploads/' });

// Configuração de logging
const logger = createLogger({
  level: 'info',
  format: format.combine(
    format.timestamp(),
    format.json()
  ),
  transports: [
    new transports.Console(),
    new DailyRotateFile({
      filename: 'logs/gateway-%DATE%.log',
      datePattern: 'YYYY-MM-DD',
      maxSize: '20m',
      maxFiles: '14d'
    })
  ]
});

// Configuração do servidor
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(bodyParser.json({ limit: '50mb' }));
app.use(bodyParser.urlencoded({ extended: true, limit: '50mb' }));

// Pool de processamento para evitar sobrecarga
const processingQueue = new pQueue({ concurrency: 4 });

// Rota para transcodificação DICOM-WEB para formato legado
app.post('/api/transcode', upload.single('dicomFile'), async (req, res) => {
  const startTime = performance.now();

  try {
    logger.info('Iniciando processamento de requisição...');

    // Verificar se o arquivo foi enviado
    if (!req.file) {
      return res.status(400).json({ error: 'Nenhum arquivo DICOM enviado' });
    }

    const filePath = req.file.path;
    const file

