### `2. Código Principal (`server.ts`)**
```typescript
import express from 'express';
import { DICOMParser } from '@dicom-parser/core';
import { DICOMWebClient } from 'dicomweb-client';
import { DICOMWebServer } from 'dicomweb-server';
import { Storage } from 'dicomweb-storage';
import { MedicalWASM } from '@medical-wasm/medical-wasm';
import { Transcoder } from 'dicomweb-transcoder';

// ===== CONFIGURAÇÕES =====
const app = express();
const port = 3000;
const gpuAccel = true;

// Inicializa WASM para GPU (OpenCL/CUDA)
const medicalWASM = new MedicalWASM({
  wasmPath: 'https://cdn.medical-wasm.org/medical-wasm.wasm',
  gpuAccel: gpuAccel,
});

// Inicializa transcodificador legado (exemplo: JSON + base64)
const transcoder = new Transcoder({
  format: 'legacy',
  wasm: medicalWASM,
});

// ===== MIDDLEWARE DE TRANSCODIFICAÇÃO =====
app.use('/api/transcode', async (req, res) => {
  try {
    const { instanceUID, studyInstanceUID } = req.query;
    if (!instanceUID || !studyInstanceUID) {
      return res.status(400).json({ error: 'Missing DICOM UIDs' });
    }

    // 1. Busca imagem via DICOMWeb (exemplo: Storage local)
    const storage = new Storage();
    const dicomData = await storage.getInstance(instanceUID);

    // 2. Parse DICOM com @dicom-parser/core (otimizado para WASM)
    const dicom = new DICOMParser();
    const parsedDicom = await dicom.parse(dicomData);

    // 3. Transcodificação acelerada por GPU (WASM)
    const transcoded = await transcoder.transcode({
      dicom: parsedDicom,
      output: {
        format: 'legacy',
        metadata: true,
        pixelData: 'base64', // Acelerado por WASM
      },
    });

    // 4. Resposta legado (exemplo: JSON + base64)
    res.json({
      status: 'success',
      data: transcoded,
      metadata: {
        studyInstanceUID,
        instanceUID,
        timestamp: new Date().toISOString(),
      },
    });
  } catch (error) {
    console.error('Transcoding error:', error);
    res.status(500).json({ error: 'Transcoding failed' });
  }
});

// ===== SERVIDOR DICOMWEB (OPCIONAL) =====
const dicomWebServer = new DICOMWebServer({
  port: 8080,
  storage: new Storage(),
});
dicomWebServer.start();

// ===== ROTA DE SAÚDE =====

