# Service Worker Completo para PWA com Cache Offline e Notificações Push

Aqui está um código completo para um Service Worker que implementa:
- Cache dinâmico com estratégias de fallback
- Suporte offline completo
- Notificações Push com Web Push API
- Integração com bibliotecas populares de PWA

```javascript
// service-worker.js

// Versão da aplicação para controle de cache
const CACHE_VERSION = 'v1.0.2';
const CACHE_NAME = `pwa-cache-${CACHE_VERSION}`;

// Cache para recursos estáticos (HTML, CSS, JS)
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/styles/main.css',
  '/scripts/main.js',
  '/manifest.webmanifest',
  '/icons/icon-72x72.png',
  '/icons/icon-192x192.png',
  '/icons/icon-512x512.png',
  '/offline.html'
];

// Cache para API e recursos dinâmicos
const DYNAMIC_CACHE_NAME = `${CACHE_NAME}-dynamic`;

// Configurações de notificações push
const NOTIFICATIONS_KEY = 'push-notifications';
const NOTIFICATIONS_OPTIONS = {
  body: 'Você tem uma nova atualização!',
  icon: '/icons/icon-192x192.png',
  badge: '/icons/icon-512x512.png',
  vibrate: [200, 100, 200],
  data: {
    date: new Date().toISOString(),
    priority: 'high'
  }
};

// Evento de instalação
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        console.log('Cache aberto:', CACHE_NAME);
        return cache.addAll(ASSETS_TO_CACHE);
      })
      .then(() => {
        self.skipWaiting(); // Permite que o SW atualize imediatamente
      })
  );
});

// Evento de ativação (limpa caches antigos)
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames
          .filter((name) => name !== CACHE_NAME && name !== `${CACHE_NAME}-dynamic`)
          .map((name) => caches.delete(name))
      );
    })
  );
  self.clients.claim(); // Permite controle dos clientes existentes
});

// Intercepta requisições para recursos estáticos
self.addEventListener('fetch', (event) => {
  // Não interceptar requisições para APIs ou recursos dinâmicos
  if (event.request.url.startsWith(self.location.origin + '/api/') ||
      event.request.url.includes('?') ||
      event.request.headers.get('range')) {
    return;
  }

  event.respondWith(
    caches.match(event.request)
      .then((cachedResponse) => {
        // Se houver resposta no cache, usá-la
        if (cachedResponse) {
          return cachedResponse;
        }

        // Senão, fazer requisição à rede e armazenar no cache
        return fetch(event.request)
          .then((networkResponse) => {
            if (!networkResponse || networkResponse.status !== 200 || networkResponse.type !== 'basic') {
              return networkResponse;
            }

            // Clonar a resposta para armazenar no cache
            const responseToCache = networkResponse.clone();

            // Armazenar no cache dinâmico
            caches.open(DYNAMIC_CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

```javascript
// service-worker.js
const CACHE_NAME = 'pwa-cache-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/styles/main.css',
  '/scripts/main.js',
  '/manifest.json',
  '/icons/icon-72x72.png',
  '/icons/icon-192x192.png',
  '/icons/icon-512x512.png',
  '/offline.html'
];

// Cache de assets estáticos
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS_TO_CACHE))
      .then(() => self.skipWaiting())
  );
});

// Atualização de cache
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

// Cache dinâmico para páginas recentes
const dynamicCache = new Set();

self.addEventListener('fetch', (event) => {
  // Não interceptar requisições para APIs ou assets estáticos
  if (event.request.mode === 'navigate' || event.request.destination === 'document') {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        if (cachedResponse) {
          return cachedResponse;
        }

        return fetch(event.request)
          .then((networkResponse) => {
            // Clonar a resposta para armazenar no cache
            const responseToCache = networkResponse.clone();

            // Salvar no cache dinâmico se for uma página HTML
            if (event.request.destination === 'document') {
              dynamicCache.add(event.request.url);
              caches.open(CACHE_NAME)
                .then((cache) => cache.put(event.request, responseToCache));
            }

            return networkResponse;
          })
          .catch(() => {
            // Retornar o offline.html se não houver resposta
            return caches.match('/offline.html');
          });
      })
    );
  }
});

// Web Push Notification
let pushNotificationSubscription = null;

self.addEventListener('push', (event) => {
  const data = event.data?.json();
  const options = {
    body: data?.body || 'Nova mensagem recebida!',
    icon: '/icons/icon-192x192.png',
    badge: '/icons/icon-192x192.png',
    data: data || {}
  };

  event.waitUntil(
    self.registration.showNotification(data?.title || 'Push Notification', options)
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil(
    clients.openWindow(event.notification.data.url || '/')
  );
});

// Verificação de atualização
self.addEventListener('fetch', (event) => {
  if (event.request.mode === 'navigate' || event.request.destination === 'document') {
    event.respondWith(
      caches.match(event.request).then((cachedResponse) => {
        if (cachedResponse) {
          return cachedResponse;
        }

        const fetchRequest = fetch(event.request);

        // Atualizar cache com a nova versão
        fetchRequest.then((response) => {
          if (!response || response.status !== 200 || response.type !== 'basic') {
            return;
          }

          const responseClone = response.clone();
          caches.open(CACHE_NAME).then((cache) => {
            cache.put(event.request, responseClone);
          });
        });

        return fetchRequest;
      })

