### **`sw.js` (Service Worker)**
```javascript
// Importar bibliotecas ativas do npm (workbox)
import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { StaleWhileRevalidate, NetworkFirst, NetworkOnly } from 'workbox-strategies';
import { BackgroundSyncPlugin } from 'workbox-background-sync';
import { ExpirationPlugin } from 'workbox-expiration';
import { clientsClaim } from 'workbox-core';

// Configuração inicial do Service Worker
self.addEventListener('install', (event) => {
  // Precaching de assets estáticos (usando Workbox)
  precacheAndRoute(self.__WB_MANIFEST);

  // Ativar controle imediato dos clientes (para melhor UX)
  clientsClaim();
});

// Configuração de estratégias de cache
const cacheStrategies = {
  // Fallback offline para páginas principais (ex: index.html)
  fallbackPages: new StaleWhileRevalidate({
    cacheName: 'fallback-pages',
    plugins: [
      new ExpirationPlugin({ maxEntries: 10 }),
    ],
  }),

  // Recarregar conteúdo dinâmico quando disponível (ex: APIs)
  dynamicContent: new NetworkFirst({
    cacheName: 'dynamic-content',
    plugins: [
      new ExpirationPlugin({ maxEntries: 50 }),
    ],
  }),

  // Priorizar rede para assets críticos (ex: CSS/JS)
  criticalAssets: new NetworkOnly({
    cacheName: 'critical-assets',
    plugins: [
      new ExpirationPlugin({ maxEntries: 10 }),
    ],
  }),
};

// Registrar rotas para estratégias de cache
registerRoute(
  /\.(?:js|css|jpg|jpeg|png|gif|svg|woff2?|ttf|eot)$/,
  cacheStrategies.criticalAssets,
  'GET'
);

registerRoute(
  /^https:\/\/api\.meusite\.com\/.*/,
  cacheStrategies.dynamicContent,
  'GET'
);

// Fallback para páginas principais (ex: index.html)
registerRoute(
  /^\/$/,
  cacheStrategies.fallbackPages,
  'GET'
);

// Configuração de Web Push Notifications
let pushSubscription = null;

self.addEventListener('push', (event) => {
  const data = event.data?.json();

  event.waitUntil(
    (async () => {
      const options = {
        body: data?.body || 'Nova atualização disponível!',
        icon: '/icons/icon-192x192.png',
        badge: '/icons/badge.png',
        vibrate: [200, 100, 200],
        data: {
          url: data?.url || '/',
        },
      };

      return self.registration.showNotification(data?.title || 'Atualização', options);
    })()
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  event.waitUntil(
    clients.openWindow(event.notification.data.url || '/')
  );
});

// Configuração de Background Sync (para sincronizar tarefas offline)
const backgroundSyncPlugin = new BackgroundSyncPlugin('queue

