```javascript
const express = require('express');
const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const { JSDOM } = require('jsdom');
const app = express();
const PORT = 3000;

// Middleware para processar uploads
app.use(express.json({ limit: '50mb' }));
app.use(express.urlencoded({ extended: true, limit: '50mb' }));
app.use(express.static('uploads'));

// Rota para converter HTML/JSON para PDF
app.post('/convert-to-pdf', async (req, res) => {
    try {
        const { fileType, data } = req.body;

        let htmlContent;
        if (fileType === 'html') {
            htmlContent = data;
        } else if (fileType === 'json') {
            // Processar JSON para HTML (simplificado)
            const jsonData = JSON.parse(data);
            const dom = new JSDOM(`
                <!DOCTYPE html>
                <html>
                    <head>
                        <style>
                            body { font-family: Arial, sans-serif; }
                            table { border-collapse: collapse; width: 100%; }
                            th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                            th { background-color: #f2f2f2; }
                            .container { max-width: 800px; margin: 0 auto; }
                        </style>
                    </head>
                    <body>
                        <div class="container">
                            ${convertJsonToHtml(jsonData)}
                        </div>
                    </body>
                </html>
            `);
            htmlContent = dom.serialize();
        } else {
            return res.status(400).send('Tipo de arquivo inválido. Aceita-se "html" ou "json".');
        }

        // Salvar o HTML temporariamente
        const tempHtmlPath = path.join(__dirname, 'temp.html');
        fs.writeFileSync(tempHtmlPath, htmlContent);

        // Configurações avançadas para Puppeteer
        const options = {
            args: [
                '--no-sandbox',
                '--disable-setuid-sandbox',
                '--headless',
                '--disable-gpu',
                '--window-size=1024,768',
                '--print-to-pdf'
            ],
            ignoreHTTPSErrors: true
        };

        // Iniciar o navegador e gerar PDF
        const browser = await puppeteer.launch(options);
        const page = await browser.newPage();

        await page.goto(`file://${tempHtmlPath}`, {
            waitUntil: 'networkidle2',
            timeout: 60000
        });

        // Configurações de impressão
        await page.pdf({
            path: path.join(__dirname, 'output.pdf'),
            format: 'A4',
            printBackground: true,
            margin: {
                top: '20mm',
                right: '20mm',
                bottom: '20mm',
                left: '20mm'
            },
            headerTemplate: `<div style="font-size: 12px; color: #999;">
                <span>Documento Gerado em ${new Date().toLocaleDateString()}</span>
            </div>`,
            footerTemplate: `<div style="font-size: 10px; color: #999;">
                <span>Página <span id="page-number"></span> de <span id="page-count"></span></span>
            </div>`,
            preferCSSPageSize: true
        });

        await browser.close();

        // Enviar o PDF para o cliente

