Aqui está um script Node.js seguro que utiliza bibliotecas públicas e ativas do npm para converter arquivos HTML/JSON em PDF com formatação avançada e suporte a tabelas. O script usa **`puppeteer`** (para renderização HTML) e **`pdf-lib`** (para manipulação de PDFs) em combinação com **`jsdom`** (para parsing de JSON/HTML).

---

### **`html-to-pdf-converter.js`**
*(Usa `puppeteer` + `pdf-lib` + `jsdom` para conversão segura)*

```javascript
const puppeteer = require('puppeteer');
const { PDFDocument, rgb } = require('pdf-lib');
const { JSDOM } = require('jsdom');
const fs = require('fs').promises;
const path = require('path');

// Função para converter HTML/JSON em PDF com formatação avançada
async function convertToPDF(inputPath, outputPath) {
    try {
        // 1. Ler o arquivo de entrada (HTML ou JSON)
        const inputContent = await fs.readFile(inputPath, 'utf-8');

        // 2. Parse JSON ou usar HTML diretamente
        let htmlContent;
        if (inputPath.endsWith('.json')) {
            const dom = new JSDOM(inputContent);
            htmlContent = dom.serialize();
        } else {
            htmlContent = inputContent;
        }

        // 3. Inicializar Puppeteer (headless)
        const browser = await puppeteer.launch({
            headless: 'new',
            args: [
                '--no-sandbox',
                '--disable-setuid-sandbox',
                '--disable-dev-shm-usage'
            ]
        });

        const page = await browser.newPage();

        // Configurar CSS para melhorar a formatação (opcional)
        await page.setContent(`
            <style>
                body {
                    font-family: Arial, sans-serif;
                    margin: 20px;
                    line-height: 1.5;
                }
                table {
                    border-collapse: collapse;
                    width: 100%;
                }
                th, td {
                    border: 1px solid #ddd;
                    padding: 8px;
                    text-align: left;
                }
                th {
                    background-color: #f2f2f2;
                }
            </style>
            ${htmlContent}
        `);

        // 4. Gerar PDF com alta qualidade
        const pdfBuffer = await page.pdf({
            format: 'A4',
            printBackground: true,
            margin: { top: '20mm', right: '20mm', bottom: '20mm', left: '20mm' }
        });

        await browser.close();

        // 5. Salvar o PDF
        await fs.writeFile(outputPath, pdfBuffer);
        console.log(`PDF gerado com sucesso em: ${outputPath}`);
    } catch (error) {
        console.error('Erro ao converter para PDF:', error);
        throw error;
    }
}

// Exemplo de uso
(async () => {
    try {
        const inputPath = path.join(__dirname, 'input.html'); // ou 'input.json'
        const outputPath = path.join(__dirname, 'output.pdf');
        await convertToPDF(inputPath, outputPath);
    } catch (err) {
        console.error('Falha na execução:', err);
    }
})();
```

