from fastapi import FastAPI, HTTPException, Depends
from sqlalchemy import create_engine, Column, Integer, String, Float
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker
from pydantic import BaseModel
from typing import List, Optional

DATABASE_URL = "sqlite:///./products.db"
engine = create_engine(DATABASE_URL)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()

class Product(Base):
    __tablename__ = "products"

    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, index=True)
    description = Column(String)
    price = Column(Float)
    stock = Column(Integer)

class ProductCreate(BaseModel):
    name: str
    description: Optional[str] = None
    price: float
    stock: int

    class Config:
        orm_mode = True

class ProductUpdate(BaseModel):
    name: Optional[str] = None
    description: Optional[str] = None
    price: Optional[float] = None
    stock: Optional[int] = None

    class Config:
        orm_mode = True

class ProductRead(BaseModel):
    id: int
    name: str
    description: Optional[str] = None
    price: float
    stock: int

    class Config:
        orm_mode = True

def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()

def get_products(db: Session = Depends(get_db)):
    return db.query(Product).all()

def get_product(db: Session = Depends(get_db), product_id: int):
    product = db.query(Product).filter(Product.id == product_id).first()
    if product is None:
        raise HTTPException(status_code=404, detail="Product not found")
    return product

def create_product(db: Session = Depends(get_db), product: ProductCreate):
    db_product = Product(
        name=product.name,
        description=product.description,
        price=product.price,
        stock=product.stock
    )
    db.add(db_product)
    db.commit()
    db.refresh(db_product)
    return db_product

def update_product(db: Session = Depends(get_db), product_id: int, product: ProductUpdate):
    db_product = db.query(Product).filter(Product.id == product_id).first()
    if db_product is None:
        raise HTTPException(status_code=404, detail="Product not found")
    for field in product:
        if getattr(product, field) is not None:
            setattr(db_product, field, getattr(product, field))
    db.commit()
    db.refresh(db_product)
    return db_product

def delete_product(db: Session = Depends(get_db), product_id: int):
    db_product = db.query(Product).filter(Product.id == product_id).first()
    if db_product is None:
        raise HTTPException(status_code=404, detail="Product not found")
    db.delete(db_product)
    db.commit()
    return {"message": "Product deleted"}

app = FastAPI()

@app.get("/products", response_model=List[ProductRead])
def read_products():
    return get_products()

@app.get("/products/{product_id}", response_model=ProductRead)
def read_product(product_id: int):
    return get_product(product_id)

@app.post("/products", response_model=ProductRead)
def create_product_endpoint(product: ProductCreate):
    return create_product(product)

@app.put("/products/{product_id}", response_model=ProductRead)
def update_product_endpoint(product_id: int, product: ProductUpdate):
    return update_product(product_id, product)

@app.delete("/products/{product_id}")
def delete_product_endpoint(product_id: int):
    return delete_product(product_id)

if __name__ == "__main__":
    Base.metadata.create_all(bind=engine)
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
```

