# -*- coding: utf-8 -*-
"""
FastAPI CRUD RESTful API for Products using SQLAlchemy.
"""

# Import statements
from fastapi import FastAPI, HTTPException, Depends, status
from pydantic import BaseModel
from typing import List, Optional

from sqlalchemy import create_engine, Column, Integer, String, Float
from sqlalchemy.orm import declarative_base, sessionmaker, Session

# Database setup
SQLALCHEMY_DATABASE_URL = "sqlite:///./test.db"
engine = create_engine(
    SQLALCHEMY_DATABASE_URL, connect_args={"check_same_thread": False}
)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

Base = declarative_base()


# SQLAlchemy model
class Product(Base):
    __tablename__ = "products"

    id = Column(Integer, primary_key=True, index=True)
    name = Column(String, index=True, nullable=False)
    description = Column(String, nullable=True)
    price = Column(Float, nullable=False)
    stock_quantity = Column(Integer, default=0, nullable=False)


# Pydantic schemas
class ProductCreate(BaseModel):
    name: str
    description: Optional[str] = None
    price: float
    stock_quantity: int


class ProductRead(BaseModel):
    id: int
    name: str
    description: Optional[str] = None
    price: float
    stock_quantity: int

    class Config:
        orm_mode = True


# Dependency to get DB session
def get_db() -> Session:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


# CRUD operations
def create_product(db: Session, product_in: ProductCreate) -> Product:
    db_product = Product(
        name=product_in.name,
        description=product_in.description,
        price=product_in.price,
        stock_quantity=product_in.stock_quantity,
    )
    db.add(db_product)
    db.commit()
    db.refresh(db_product)
    return db_product


def get_product(db: Session, product_id: int) -> Optional[Product]:
    return db.query(Product).filter(Product.id == product_id).first()


def get_products(db: Session) -> List[Product]:
    return db.query(Product).all()


def update_product(
    db: Session, product_id: int, product_in: ProductCreate
) -> Optional[Product]:
    db_product = get_product(db, product_id)
    if not db_product:
        return None
    for field, value in product_in.dict().items():
        setattr(db_product, field, value)
    db.commit()
    db.refresh(db_product)
    return db_product


def delete_product(db: Session, product_id: int) -> Optional[Product]:
    db_product = get_product(db, product_id)
    if not db_product:
        return None
    db.delete(db_product)
    db.commit()
    return db_product


# FastAPI app and routes
app = FastAPI(title="Product CRUD API")


@app.post(
    "/products/",
    response_model=ProductRead,
    status_code=status.HTTP_201_CREATED,
)
def create_product_endpoint(
    product_in: ProductCreate, db: Session = Depends(get_db)
):
    return create_product(db, product_in)


@app.get("/products/{product_id}", response_model=ProductRead)
def read_product_endpoint(
    product_id: int, db: Session = Depends(get_db)
):
    db_product = get_product(db, product_id)
    if not db_product:
        raise HTTPException(status_code=404, detail="Product not found")
    return db_product


@app.get("/products/", response_model=List[ProductRead])
def read_products_endpoint(db: Session = Depends(get_db)):
    return get_products(db)


@app.put("/products/{product_id}", response_model=ProductRead)
def update_product_endpoint(
    product_id: int, product_in: ProductCreate, db: Session = Depends(get_db)
):
    db_product = update_product(db, product_id, product_in)
    if not db_product:
        raise HTTPException(status_code=404, detail="Product not found")
    return db_product


@app.delete(
    "/products/{product_id}",
    status_code=status.HTTP_204_NO_CONTENT,
)
def delete_product_endpoint(product_id: int, db: Session = Depends(get_db)):
    db_product = delete_product(db, product_id)
    if not db_product:
        raise HTTPException(status_code=404, detail="Product not found")
    return None


# Run the app with: uvicorn main:app --reload
if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
```

