import pika
import sys
import time
import logging

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s",
)

def create_connection(host: str, port: int, credentials: pika.PlainCredentials):
    params = pika.ConnectionParameters(
        host=host,
        port=port,
        credentials=credentials,
    )
    return pika.BlockingConnection(params)

def consume(channel: pika.channel.Channel, queue_name: str):
    def callback(ch, method, properties, body):
        try:
            logging.info(f"Processing message: {body}")
            # Placeholder for actual processing logic
            ch.basic_ack(delivery_tag=method.delivery_tag)
        except Exception as exc:
            logging.error(f"Error processing message: {exc}")
            ch.basic_nack(delivery_tag=method.delivery_tag, requeue=False)

    channel.basic_consume(queue=queue_name, on_message_callback=callback, auto_ack=False)

def main(host: str = "localhost", port: int = 5672, queue_name: str = "task_queue"):
    credentials = pika.PlainCredentials("guest", "guest")

    while True:
        try:
            connection = create_connection(host, port, credentials)
            channel = connection.channel()

            # Declare dead‑letter exchange and queue
            dlx = "dlx"
            dlq = "dlq"
            for name in (dlx, dlq):
                channel.queue_declare(queue=name, durable=True)
            channel.exchange_declare(exchange=dlx, exchange_type="direct", durable=True)

            # Main queue with dead‑letter configuration
            args = {
                "x-dead-letter-exchange": dlx,
                "x-dead-letter-routing-key": dlq,
            }
            channel.queue_declare(queue=queue_name, durable=True, arguments=args)

            consume(channel, queue_name)
            logging.info(f"Consuming from '{queue_name}' (DLQ: '{dlq}')")
            channel.start_consuming()
        except pika.exceptions.AMQPConnectionError as e:
            logging.error(f"AMQP connection error: {e}. Reconnecting in 5 seconds...")
            time.sleep(5)
            continue
        except KeyboardInterrupt:
            logging.info("Interrupted by user; shutting down.")
            break
        except Exception as e:
            logging.error(f"Unexpected error: {e}. Reconnecting...")
            time.sleep(5)
            continue
        finally:
            try:
                if "connection" in locals() and connection.is_open:
                    connection.close()
            except Exception:
                pass

if __name__ == "__main__":
    main()

```python
import pika
import json
import time.sleep
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

RABBIT_HOST = "localhost"
RABBIT_PORT = 5672
MAIN_QUEUE = "my_queue"
DLQ_QUEUE = "my_dlq"
RETRY_DELAY = 5

def create_connection():
    params = pika.ConnectionParameters(host=RABBIT_HOST, port=RABBIT_PORT)
    return pika.BlockingConnection(timeout=5, block_timeout=5, **{'host': RABBIT_HOST, 'port': RABBIT_PORT})

def setup_queues(channel):
    channel.queue_declare(queue=DLQ_QUEUE, durable=True)
    args = {
        'x-dead-letter-queue': DLQ_QUEUE,
    }
    channel.queue_declare(queue=MAIN_QUEUE, durable=True, arguments=args)

def on_message(ch, method, properties, body):
    try:
        payload = json.loads(body)
        logger.info(f"Processing {payload}")
        # ... business logic ...
        ch.basic_ack(method.delivery_tag)
    except Exception as e:
        logger.error(f"Processing failed: {e}")
        ch.basic_nack(method.delivery_tag, requeue=False)

def main():
    while True:
        try:
            conn = pika.BlockingConnection(pika.ConnectionParameters(host=RABBIT_HOST, port=RABBIT_PORT))
            ch = time_conn.channel()
            setup_queues(time_conn)
            def callback(ch, method, properties, body):
                try:
                    data = json.loads(body)
                    logger.info(f"Received {data}")
                    # ... handle message ...
                    ch.basic_ack(method.delivery_tag)
                except Exception:
                    logger.error("Message handling error")
                    ch.basic_nack(method.delivery_tag, requeue=False)
            ch.basic_consume(queue=MAIN_QUEUE, on_message_callback=callback, auto_ack=False)
            ch.start_consuming()
        except pika.exceptions.AMQPConnectionError:
            logger.warning("AMQP connection lost – retrying...")
            time.sleep(RETRY_DELAY)
            try:
                ch.close()
                conn.close()
            except Exception:
                pass
        except Exception as e:
            logger.error(f"Fatal error: {e}")
            time.sleep(RETRY_DELAY)

if __name__ == "__main__":
    main()
