// ====================  MODELO (SCHEMA)  ====================
const userSchema = new mongoose.Schema({
  name:  { type: String, required: true },
  email: { type: String, required: true, unique: true, lowercase: true },
  // campos adicionais podem ser inseridos aqui (ex.: age, avatar, etc.)
});

const User = mongoose.model('User', userSchema);

// ====================  ROTAS RESTRFUL  ====================

// GET /users – lista todos os usuários
app.get('/users', async (req, res) => {
  try {
    const users = await User.find();
    res.json(users);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// GET /users/:id – obtém um usuário pelo ID
app.get('/users/:id', async (req, res) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) return res.status(404).json({ message: 'Usuário não encontrado' });
    res.json(user);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// POST /users – cria um novo usuário
app.post('/users', async (req, res) => {
  const { name, email } = req.body;
  const novoUser = new User({ name, email });

  try {
    const userSalvo = await novoUser.save();
    res.status(201).json(userSalvo);
  } catch (err) {
    // Duplicidade de e‑mail (código 11000 do MongoDB)
    if (err.code === 11000) {
      return res.status(400).json({ message: 'E‑mail já cadastrado' });
    }
    res.status(400).json({ message: err.message });
  }
});

// PUT /users/:id – atualiza um usuário existente
app.put('/users/:id', async (req, res) => {
  try {
    const user = await User.findById(req.params.id);
    if (!user) return res.status(404).json({ message: 'Usuário não encontrado' });

    const { name, email } = req.body;
    if (name) user.name = name;
    if (email) user.email = email;

    const userAtualizado = await user.save();
    res.json(userAtualizado);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// DELETE /users/:id – remove um usuário
app.delete('/users/:id', async (req, res) => {
  try {
    const user = await User.findByIdAndDelete(req.params.id);
    if (!user) return res.status(404).json({ message: 'Usuário não encontrado' });
    res.json({ message: 'Usuário excluído' });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// ====================  HANDLING OF UNHANDLED ROUTES  ====================
app.use((req, res) => {
  res.status(404).json({ message: 'Rota não encontrada' });
});

// ====================  START SERVER  ====================
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Servidor rodando em http://localhost:${PORT}`);
});
```

**Observações**

* O código usa **CommonJS** (`require`) para maior compatibilidade, mas pode ser trocado por `import` caso o projeto utilize *ES Modules* (`.mjs` ou `"type": "module"` no `package.json`).
* O esquema do usuário contém apenas `name` e `email`, mas pode ser ampliado conforme a necessidade.
* As rotas implementam as operações **C**reate, **R**ead (listagem e detalhe), **U**pdate e **D**elete – o padrão RESTful.
* Há tratamento de erros comuns (404, 400, 500) e de integridade de dados (e‑mail duplicado).  
* Para rodar a aplicação, certifique‑se de ter o MongoDB instalado ou uma URI válida no `.env` (`MONGODB_URI`).  
* Instale as dependências com:

```bash
npm install express mongoose dotenv
```

E então inicie:

```bash
node caminho/para/seu/arquivo.js
```

```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const helmet = require('helmet');
const dotenv = require('dotenv');
const { body, param, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();
const PORT = process.env.PORT || 3000;

// Load .env file
dotenv.config();

// Security middlewares
app.use(helmet());
app.use(cors());
app.use(morgan('dev'));
app.use(express.json());

// MongoDB connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
})
.then(() => console.log('✅ Connected to MongoDB'))
.catch(err => console.error('❌ MongoDB connection error:', err));

// Mongoose schema & model
const userSchema = new mongoose.Schema({
  name: { type: String, required: true, trim: true },
  email: { type: String, required: true, unique: true, lowercase: true, trim: true },
}, { timestamps: true });

const User = mongoose.model('User', userSchema);

// Utility to catch async errors
const asyncHandler = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// Validation chain
const userValidationRules = [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ max: 100 }).withMessage('Name must be <= 100 characters'),
  body('email')
    .trim()
    .isEmail().withMessage('Valid email required')
    .normalizeEmail(),
];

// GET /users - list all users
app.get('/users', asyncHandler(async (req, res) => {
  const users = await User.find().select('-__v');
  res.json(users);
}));

// GET /users/:id - get single user
app.get('/users/:id',
  param('id').isMongoId().withMessage('Invalid MongoDB ID'),
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const user = await User.findById(req.params.id).select('-__v');
    if (!user) return res.status(404).json({ message: 'User not found' });
    res.json(user);
  })
);

// POST /users - create new user
app.post('/users',
  userValidationRules,
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { name, email } = req.body;
    const newUser = new User({ name, email });
    await newUser.save();

    res.status(201).json(newUser);
  })
);

// PUT /users/:id - update user
app.put('/users/:id',
  userValidationRules,
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { id } = req.params;
    if (!mongoose.Types.ObjectId.isValid(id)) return res.status(400).json({ message: 'Invalid ID format' });

    const updates = req.body;
    const user = await User.findByIdAndUpdate(id, updates, { new: true, runValidators: true }).select('-__v');

    if (!user) return res.status(404).json({ message: 'User not found' });
    res.json(user);
  })
);

// DELETE /users/:id - delete user
app.delete('/users/:id',
  param('id').isMongoId().withMessage('Invalid MongoDB ID'),
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { id } = req.params;
    const user = await User.findByIdAndDelete(id);
    if (!user) return res.status(404).json({ message: 'User not found' });
    res.json({ message: 'User deleted' });
  })
);

// Global error handler
app.use((err, req, res, next) => {
  console.error('❌ Error:', err);
  res.status(500).json({ message: 'Internal Server Error' });
});

app.listen(PORT, () => {
  console.log(`🚀 Server running on http://localhost:${PORT}`);
});
```

