const {
  GW_PORT = 3000,
  GW_HOST = '0.0.0.0',
  // DICOM‑Web server base URL (e.g. Orthanc, DCM4CHEE, custom)
  DICOM_WEB_BASE = 'http://localhost:8042/dicom-web',
  // Optional FFmpeg path (if you want to force a specific binary)
  FFMPEG_PATH = null
} = process.env;

// ---------------------------------------------------------------------------
// Initialise Express app
const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helper: create a DICOM‑Web client (singleton)
