```js
// Required libraries (install via npm):
// - express: web framework
// - dicomweb-client: DICOM‑Web retrieval client
// - sharp: GPU‑accelerated image processing (libvips compiled with GPU support)
// - node-fetch (optional): for remote DICOM‑Web server configuration

const express = require('express');
const { DICOMWebClient } = require('dicomweb-client');
const sharp = require('sharp');
const fetch = require('node-fetch'); // only needed if you fetch server metadata

const app = express();
app.use(express.json());

/**
 * Middleware that converts a DICOM‑Web request to a legacy proprietary format.
 * Expects query parameters: StudyInstanceUID and SOPClassUID.
 * The DICOM‑Web server URL can be passed via header `x-dicomweb-server`.
 */
function legacyGateway(req, res, next) {
  const studyUID = req.query.StudyInstanceUID;
  const sopClassUID = req.query.SOPClassUID;
  const dcmWebBase = req.headers['x-dicomweb-server'] || 'https://example-dicomweb-server';

  // Create a client for this request (handles CORS, auth, etc.)
  const client = new DICOMWebClient({
    url: dcmWebBase,
  });

  // Retrieve the DICOM object
  client.retrieveInstance(studyUID, sopClassUID)
    .then(dataset => {
      // Raw pixel data is a Uint8Array; convert to Buffer for processing
      const pixelBuffer = Buffer.from(dataset.PixelData);

      // GPU‑accelerated transcoding (sharp uses libvips which can leverage GPU)
      return sharp(pixelBuffer)
        .rotate()               // example GPU‑friendly operation
        .toFormat('png')        // output format required by the legacy system
        .toBuffer();
    })
    .then(legacyImageBuffer => {
      // Wrap the transcoded image in a simple legacy proprietary header
      const LEGACY_HEADER = Buffer.from('LEGACY\x00\x01\x02\x03'); // adapt to real spec
      const legacyPayload = Buffer.concat([LEGACY_HEADER, legacyImageBuffer]);

      // Respond with the proprietary format
      res.set('Content-Type', 'application/octet-stream');
      res.send(legacyPayload);
    })
    .catch(err => {
      console.error('Conversion error:', err);
      res.status(500).send('Conversion failed');
    });
}

// Register the middleware on the desired endpoint
app.use('/gateway', legacyGateway);

// Start the HTTP server
const PORT = process.env.PORT || 8080;
app.listen(PORT, () => {
  console.log(`Legacy DICOM‑Web gateway listening on port ${PORT}`);
});
```

