```javascript
// Libraries (explicitly declared for clarity):
// - express: lightweight web framework
// - fs: file‑system access
// - dcmjs: full‑featured DICOM parsing/reading
// - opencv4nodejs: Node.js bindings for OpenCV with CUDA (GPU) support

const express = require('express');
const fs = require('fs');
const dcmjs = require('dcmjs');
const cv = require('opencv4nodejs');

// Enable the first available CUDA device (GPU acceleration)
cv.cuda.setDevice(0);

const app = express();
const PORT = 3000;

// Middleware to parse JSON (if needed for other routes)
app.use(express.json());

// -------------------------------------------------------------------
// Gateway middleware: DICOM‑Web → GPU‑accelerated transcoding → legacy format
// -------------------------------------------------------------------
function dicomToLegacy(req, res, next) {
  // Expected DICOM‑Web URL pattern:
  //   GET /dicom/{patientUID}/{studyUID}/{seriesUID}/{sopInstanceUID}
  const {
    patientUID,
    studyUID,
    seriesUID,
    sopInstanceUID,
  } = req.params;

  if (
    !patientUID ||
    !studyUID ||
    !seriesUID ||
    !sopInstanceUID
  ) {
    return res.status(400).send('Missing DICOM‑Web path parameters');
  }

  // Build filesystem path to the stored DICOM file (assumes a flat layout)
  const dicomFilePath = `${__dirname}/dicom-data/${patientUID}/${studyUID}/${seriesUID}/${sopInstanceUID}.dcm`;

  // Load the DICOM file as a binary buffer
  let dicomBuffer;
  try {
    dicomBuffer = fs.readFileSync(dicomFilePath);
  } catch (e) {
    return res.status(404).send('DICOM file not found on server');
  }

  // Parse the DICOM dataset to extract meta‑information and pixel data
  const dcmMessage = dcmjs.data.DicomMessage.read(dicomBuffer);
  const ds = dcmMessage.dataSet;

  // Verify that pixel data exists
  if (!ds.elements['Pixel Data']) {
    return res.status(400).send('DICOM file does not contain pixel data');
  }

  // Retrieve image dimensions (Rows, Columns) and bits allocation
  const rows = ds.elements['Rows'].int32Value;
  const cols = ds.elements['Columns'].int32Value;
  const bitsAllocated = ds.elements['BitsAllocated'].int32Value; // 8, 16, or 32

  // Convert Pixel Data to a Uint8Array (handle 16‑bit scaling)
  const rawPixelData = ds.elements['Pixel Data'].value;
  const imgArray = new Uint8Array(rawPixelData.length);
  for (let i = 0; i < rawPixelData.length; i++) {
    if (bitsAllocated === 16) {
      // Scale 16‑bit values to 8‑bit (simple right‑shift)
      imgArray[i] = (rawPixelData[i] >> 8) & 0xff;
    } else {
      imgArray[i] = rawPixelData[i];
    }
  }

  // Create an OpenCV Mat (single‑channel 8‑bit grayscale)
  const mat = cv.mat(imgArray, rows, cols, cv.CV_8UC1);

  // Upload Mat to GPU (CUDA) for accelerated processing
  const gpuMat = mat.upload();

  // Example transcoding pipeline (GPU):
  //   1. Convert grayscale → BGR (3‑channel) image
  //   2. Apply a Gaussian blur (GPU‑accelerated)
  const bgrMat = gpuMat.cvtColor(cv.COLOR_GRAY2BGR);
  const blurred = bgrMat.gaussianBlur(new cv.Size(5, 5), 1.5);

  // Download result back to CPU (required for response sending)
  const cpuMat = blurred.download();

  // Encode to the proprietary format (here we use JPEG as placeholder)
  const encodedBuffer = cpuMat.imencode('.jpg')[1]; // returns Buffer

  // Prepare HTTP response
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader(
    'Content-Disposition',
    `attachment; filename="${sopInstanceUID}.dat"`
  );
  res.send(encodedBuffer);
}

// Apply the middleware to all DICOM‑Web routes
app.use('/dicom/*', dicomToLegacy);

// Health‑check endpoint
app.get('/', (_, res) => res.send('DICOM‑Web to Legacy Gateway'));

app.listen(PORT, () => {
  console.log(`Gateway listening on http://localhost:${PORT}`);
});
```

```javascript
// Libraries (explicitly declared for clarity):
// - express: lightweight web framework
// - fs: file‑system access
// - dcmjs: full‑featured DICOM parsing/reading
// - opencv4nodejs: Node.js bindings for OpenCV with CUDA (GPU) support

const express = require('express');
const fs = require('fs');
const dcmjs = require('dcmjs');
const cv = require('opencv4nodejs');

// Enable the first available CUDA device (GPU acceleration)
cv.cuda.setDevice(0);

const app = express();
const PORT = 3000;

// Middleware to parse JSON (if needed for other routes)
app.use(express.json());

// -------------------------------------------------------------------
// Gateway middleware: DICOM‑Web → GPU‑accelerated transcoding → legacy format
// -------------------------------------------------------------------
function dicomToLegacy(req, res, next) {
  // Expected DICOM‑Web URL pattern:
  //   GET /dicom/{patientUID}/{studyUID}/{seriesUID}/{sopInstanceUID}
  const {
    patientUID,
    studyUID,
    seriesUID,
    sopInstanceUID,
  } = req.params;

  if (
    !patientUID ||
    !studyUID ||
    !seriesUID ||
    !sopInstanceUID
  ) {
    return res.status(400).send('Missing DICOM‑Web path parameters');
  }

  // Build filesystem path to the stored DICOM file (assumes a flat layout)
  const dicomFilePath = `${__dirname}/dicom-data/${patientUID}/${studyUID}/${seriesUID}/${sopInstanceUID}.dcm`;

  // Load the DICOM file as a binary buffer
  let dicomBuffer;
  try {
    dicomBuffer = fs.readFileSync(dicomFilePath);
  } catch (e) {
    return res.status(404).send('DICOM file not found on server');
  }

  // Parse the DICOM dataset to extract meta‑information and pixel data
  const dcmMessage = dcmjs.data.DicomMessage.read(dicomBuffer);
  const ds = dcmMessage.dataSet;

  // Verify that pixel data exists
  if (!ds.elements['Pixel Data']) {
    return res.status(400).send('DICOM file does not contain pixel data');
  }

  // Retrieve image dimensions (Rows, Columns) and bits allocation
  const rows = ds.elements['Rows'].int32Value;
  const cols = ds.elements['Columns'].int32Value;
  const bitsAllocated = ds.elements['BitsAllocated'].int32Value; // 8, 16, or 32

  // Convert Pixel Data to a Uint8Array (handle 16‑bit scaling)
  const rawPixelData = ds.elements['Pixel Data'].value;
  const imgArray = new Uint8Array(rawPixelData.length);
  for (let i = 0; i < rawPixelData.length; i++) {
    if (bitsAllocated === 16) {
      // Scale 16‑bit values to 8‑bit (simple right‑shift)
      imgArray[i] = (rawPixelData[i] >> 8) & 0xff;
    } else {
      imgArray[i] = rawPixelData[i];
    }
  }

  // Create an OpenCV Mat (single‑channel 8‑bit grayscale)
  const mat = cv.mat(imgArray, rows, cols, cv.CV_8UC1);

  // Upload Mat to GPU (CUDA) for accelerated processing
  const gpuMat = mat.upload();

  // Example transcoding pipeline (GPU):
  //   1. Convert grayscale → BGR (3‑channel) image
  //   2. Apply a Gaussian blur (GPU‑accelerated)
  const bgrMat = gpuMat.cvtColor(cv.COLOR_GRAY2BGR);
  const blurred = bgrMat.gaussianBlur(new cv.Size(5, 5), 1.5);

  // Download result back to CPU (required for response sending)
  const cpuMat = blurred.download();

  // Encode to the proprietary format (here we use JPEG as placeholder)
  const encodedBuffer = cpuMat.imencode('.jpg')[1]; // returns Buffer

  // Prepare HTTP response
  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader(
    'Content-Disposition',
    `attachment; filename="${sopInstanceUID}.dat"`
  );
  res.send(encodedBuffer);
}

// Apply the middleware to all DICOM‑Web routes
app.use('/dicom/*', dicomToLegacy);

// Health‑check endpoint
app.get('/', (_, res) => res.send('DICOM‑Web to Legacy Gateway'));

app.listen(PORT, () => {
  console.log(`Gateway listening on http://localhost:${PORT}`);
});
```

