**Service Worker completo (arquivo `sw.js`)**

```js
/* -------------------------------------------------------------
   sw.js – Service Worker para PWA
   • Cache dinâmico (offline‑first) com Workbox
   • Suporte a Web Push Notifications
   • Mensagens de controle (ex.: skipWaiting)
   ------------------------------------------------------------- */

// Importa a biblioteca Workbox (precisa estar disponível no cache ou via CDN)
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.6.0/workbox-sw.js');

if (workbox) {
  console.log('[SW] Workbox carregado');
} else {
  console.error('[SW] Workbox não encontrado');
}

/* -------------------------------------------------------------
   1️⃣  Instalação – pré‑cache dos arquivos “core”
   ------------------------------------------------------------- */
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open('pwa-cache-v1').then((cache) => {
      // Lista dos arquivos que precisam estar offline (gerada em tempo de build)
      const coreAssets = [
        '/',                     // index.html
        '/index.html',
        '/manifest.json',
        '/css/styles.css',
        '/js/app.js',
        '/icons/icon-192x192.png',
        '/icons/icon-512x512.png',
        // ...adicione outros recursos críticos aqui
      ];

      return cache.addAll(coreAssets);
    })
  );
});

/* -------------------------------------------------------------
   2️⃣  Ativação – limpa caches antigos
   ------------------------------------------------------------- */
self.addEventListener('activate', (event) => {
  const cacheWhitelist = ['pwa-cache-v1']; // nomes dos caches que queremos manter

  event.waitUntil(
    caches.keys().then((keyList) => {
      return Promise.all(
        keyList.map((key) => {
          if (cacheWhitelist.indexOf(key) === -1) {
            console.log('[SW] Removendo cache antigo:', key);
            return caches.delete(key);
          }
        })
      );
    })
  );

  // Força o controlador a ficar ativo imediatamente
  self.clients.claim();
});

/* -------------------------------------------------------------
   3️⃣  Busca (fetch) – estratégia “network‑first” com fallback
   ------------------------------------------------------------- */
self.addEventListener('fetch', (event) => {
  // Só intercepta requisições GET
  if (event.request.method !== 'GET') return;

  event.respondWith(
    caches.match(event.request).then((cachedResp) => {
      // Se já estiver no cache, devolve do cache
      if (cachedResp) {
        return cachedResp;
      }

      // Tenta a rede primeiro
      return fetch(event.request)
        .then((networkResp) => {
          // Clone a resposta para poder colocá‑la no cache
          const responseToCache = networkResp.clone();

          // Salva no cache dinâmico (runtime) – nome 'pwa-cache-v1'
          caches.open('pwa-cache-v1').then((cache) => {
            // Opcional: limitar quantidade de itens ou expirar por data
            cache.put(event.request, responseToCache);
          });

          return networkResp;
        })
        .catch(() => {
          // Se falhar a rede, tenta servir do cache (offline)
          if (event.request.destination === 'document') {
            // Para navegação, garante que o index.html seja retornado
            return caches.match('/index.html');
          }

          // Caso não exista, devolve um erro genérico
          return Response.error();
        });
    })
  );
});

/* -------------------------------------------------------------
   4️⃣  Push – exibe notificação quando a mensagem chega
   ------------------------------------------------------------- */
self.addEventListener('push', (event) => {
  // O payload pode vir como JSON, texto ou blob – aqui usamos JSON
  const payload = event.data?.json() ?? {};

  const title = payload.title || 'Notificação';
  const options = {
    body: payload.body || '',
    icon: '/icons/icon-192x192.png',
    badge: '/icons/manifest.json',
    data: payload.additionalData || {}, // pode conter URL para abrir a app
    vibrate: [200, 100, 200],
    // ação opcional para quando o usuário clica na notificação
    // (não é necessária aqui, o listener de 'notificationclick' cuida disso)
  };

  event.waitUntil(
    self.registration.showNotification(title, options)
  );
});

/* -------------------------------------------------------------
   5️⃣  Notificação clicada – foca a janela ou abre a URL
   ------------------------------------------------------------- */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();

  event.waitUntil(
    // Tenta focar a janela já aberta da PWA
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      for (const client of clientList) {
        // Se a URL da notificação for a mesma da página atual, foca
        if (client.url === event.notification.data?.url) {
          return client.focus();
        }
      }

      // Se não houver janela aberta, abre uma nova
      if (clients.openWindow) {
        return clients.openWindow(event.notification.data?.url);
      }
    })
  );
});

/* -------------------------------------------------------------
   6️⃣  Mensagens (ex.: skipWaiting) vindas da página
   ------------------------------------------------------------- */
self.addEventListener('message', (event) => {
  if (!event.data) return;

  const { type } = event.data;

  if (type === 'SKIP_WAITING') {
    console.log('[SW] skipWaiting acionado');
    self.skipWaiting();
  }

  if (type === 'CLIENT_MSSG') {
    // Exemplo de comunicação entre página e SW (pode ser usado para
    // atualizar configurações, registrar push, etc.)
    console.log('[SW] Mensagem recebida:', event.data);
  }
});

/* -------------------------------------------------------------
   7️⃣  (Opcional) Configurações de Background Sync, Lifecycle,
       etc. – podem ser adicionadas conforme a necessidade.
   ------------------------------------------------------------- */
```

---

## Como usar

1. **Salvar** o código acima em um arquivo chamado `sw.js` na raiz do seu site (ou em outro caminho que faça sentido).
2. **Registrar** o Service Worker na sua página principal (ex.: `index.html`):

   ```js
   if ('serviceWorker' in navigator) {
     window.addEventListener('load', () => {
       navigator.serviceWorker.register('/sw.js')
         .then(reg => console.log('Service Worker registrado:', reg.scope))
         .catch(err => console.error('Falha ao registrar Service Worker:', err));
     });
   }
   ```

3. **Subscrição ao Push** (no cliente, por exemplo, usando o API `PushManager`):

   ```js
   // solicitar permissão de notificação
   async function requestNotificationPermission() {
     const permission = await Notification.requestPermission();
     if (permission !== 'granted') throw new Error('Permissão negada');
   }

   // inscrever no push (geralmente enviando a chave pública VAPID ao seu backend)
   async function subscribeToPush() {
     const registration = await navigator.serviceWorker.ready;
     const subscription = await registration.pushManager.subscribe({
       userVisibleOnly: true,
       applicationServerKey: urlBase64ToUint8Array(vapidPublicKey) // sua chave VAPID
     });

     // Enviar `subscription` ao seu servidor para que ele possa disparar notificações
     await fetch('/api/subscribe', {
       method: 'POST',
       headers: { 'Content-Type': 'application/json' },
       body: JSON.stringify(subscription)
     });
   }

   // Converter chave VAPID (string base64) para Uint8Array
   function urlBase64ToUint8Array(base64String) {
     const padding = '='.repeat((4 - base64String.length % 4) % 4);
     const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
     const rawData = atob(base64);
     const outputArray = new Uint8Array(rawData.length);
     for (let i = 0; i < rawData.length; i++) {
       outputArray[i] = rawData.charCodeAt(i);
     }
     return outputArray;
   }

   // Chamar as funções após o carregamento da página
   requestNotificationPermission();
   subscribeToPush();
   ```

> **Observação:** O backend (`/api/subscribe`) deve receber a subscription, armazenar a chave pública do usuário e, quando quiser, disparar a notificação via **Web Push** (usando bibliotecas como `web-push` no Node.js, por exemplo). O Service Worker acima apenas exibe a notificação quando recebe o *push event*.

---

### Principais pontos cobertos

| Funcionalidade | Como está implementada |
|----------------|------------------------|
| **Cache estático (offline)** | `install` → `caches.open('pwa-cache-v1')` + `cache.addAll([...])` |
| **Cache dinâmico (runtime)** | `fetch` → `cache.put(event.request, responseToCache)` (network‑first) |
| **Limpeza de caches antigos** | `activate` → `caches.keys()` + `caches.delete(oldName)` |
| **Web Push Notifications** | `push` event → `self.registration.showNotification()` |
| **Comunicação página ↔ SW** | `message` event (ex.: `skipWaiting`) |
| **Uso de Workbox** | `importScripts` + `workbox` (pode ser expandido para precache, routing, etc.) |

Com esse Service Worker a sua PWA ficará pronta para funcionar offline, receber notificações push e manter o controle de atualização e cache de forma robusta. Boa implementação! 🚀

```javascript
/* eslint-disable no-restricted-globals */

importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.6.0/workbox-sw.js');

const { clientsClaim } = workbox.precaching;
const { registerRoute } = workbox.routing;
const { NetworkFirst, CacheFirst } = workbox.strategies;
const { precacheAndRoute } = workbox.precaching;

// Precache static assets (the manifest can be generated by Workbox CLI or manually)
precacheAndRoute(self.__WB_MANIFEST || []);

clientsClaim();

// ---------- Caching ----------
// HTML documents – cache first, fallback to network
registerRoute(
  ({ request }) => request.destination === 'document',
  new CacheFirst({
    cacheName: 'html-cache',
    plugins: [
      new workbox.expiration.ExpirationPlugin({ maxEntries: 30, maxAgeSeconds: 30 * 24 * 60 * 60 })
    ]
  })
);

// Images, CSS, Fonts – network first with cache fallback
registerRoute(
  ({ request }) => ['image', 'style', 'font'].includes(request.destination),
  new NetworkFirst({
    cacheName: 'assets-cache',
    networkTimeoutSeconds: 10,
    plugins: [
      new workbox.expiration.ExpirationPlugin({ maxEntries: 60, maxAgeSeconds: 365 * 24 * 60 * 60 })
    ]
  })
);

// JavaScript files – network first with cache fallback
registerRoute(
  ({ request }) => request.destination === 'script',
  new NetworkFirst({
    cacheName: 'js-cache',
    networkTimeoutSeconds: 5,
    plugins: [
      new workbox.expiration.ExpirationPlugin({ maxEntries: 30, maxAgeSeconds: 365 * 24 * 60 * 60 })
    ]
  })
);

// ---------- Push Notifications ----------
self.addEventListener('push', event => {
  if (!event.data) return; // No payload, ignore

  const payload = event.data.json();
  const title = payload.title || 'Notification';
  const options = {
    body: payload.body,
    icon: '/icons/icon-192.png',
    badge: '/icons/badge.png',
    data: payload.data || {}
  };

  event.waitUntil(
    self.registration.showNotification(title, options).then(() => {
      // Optionally focus the client when notification is clicked
      return self.clients.matchAll().then(clients => {
        for (const client of clients) {
          if (client.url === options.data?.url && 'focus' in client) {
            return client.focus();
          }
        }
      });
    })
  );
});

// If push has no payload (e.g., a keep‑alive), show a generic notification
self.addEventListener('push', event => {
  if (event.data) return; // already handled above

  const title = 'Background Sync';
  const options = {
    body: 'Periodic data sync completed.',
    icon: '/icons/icon-192.png',
    badge: '/icons/badge.png',
    data: { url: '/' }
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

// ---------- Notification click ----------
self.addEventListener('notificationclick', event => {
  event.notification.close();

  event.waitUntil(
    clients.matchAll().then(clientList => {
      for (const client of clientList) {
        if (client.url === event.notification.data?.url && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(event.notification.data?.url);
      }
    })
  );
});

// ---------- Periodic Sync (optional) ----------
self.addEventListener('periodicsync', event => {
  if (event.tag === 'sync-periodic') {
    event.waitUntil(fetch('/api/sync'));
  }
});

// ---------- Subscription management ----------
self.addEventListener('subscriptionchange', event => {
  const oldSubscription = event.oldSubscription;
  const newSubscription = event.newSubscription;

  if (!newSubscription) return; // Subscription removed

  // Example: register the subscription with your backend
  newSubscription.getKey('p256dh')
    .then(key => {
      if (!key) return;
      return fetch('/api/subscription', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ endpoint: newSubscription.endpoint, key })
      });
    })
    .catch(err => console.error('Subscription registration failed:', err));
});
```

```javascript
// sw.js – Service Worker (ES Module)
import { precacheAndRoute } from 'https://cdn.jsdelivr.net/npm/workbox-precaching@6.6.0/modules/precacheAndRoute.js';
import { registerRoute } from 'https://cdn.jsdelivr.net/npm/workbox-routing@6.6.0/modules/registerRoute.js';
import { CacheFirst, NetworkFirst } from 'https://cdn.jsdelivr.net/npm/workbox-strategies@6.6.0/modules/strategies.js';

// ==== Pre‑cache core assets on install ====
const CORE_ASSETS = [
  '/',
  '/index.html',
  '/manifest.json',
  '/logo192.png',
  '/logo512.png',
  '/css/main.css',
  '/js/main.js',
  // add additional static files as needed
];

self.addEventListener('install', event => {
  event.waitUntil(
    precacheAndRoute(CORE_ASSETS)
  );
  self.skipWaiting();
});

self.addEventListener('activate', event => {
  event.waitUntil(
    self.clients.claim()
  );
});

// ==== Routing & Caching Strategy ====
// 1. HTML pages – Cache first (fallback to network)
registerRoute(
  ({ request }) => request.destination === 'document',
  new CacheFirst({
    cacheName: 'html-cache',
    plugins: []
  })
);

// 2. Static assets (CSS, JS, images) – Cache first
registerRoute(
  ({ request }) => request.destination === 'style' ||
                   request.destination === 'script' ||
                   request.destination === 'image',
  new CacheFirst({
    cacheName: 'static-assets',
    plugins: []
  })
);

// 3. API requests – Network first, fallback to cache
registerRoute(
  ({ request }) => request.url.startsWith('/api/'),
  new NetworkFirst({
    cacheName: 'api-cache',
    networkTimeoutSeconds: 15,
    plugins: []
  })
);

// ==== Push Notification Handling ====
self.addEventListener('push', event => {
  // Expect push payload as JSON: {title, body, url}
  let pushData;
  try {
    pushData = event.request.json();
  } catch (_) {
    // If payload isn’t JSON, use defaults
    pushData = {
      title: 'PWA Notification',
      body: 'You have a new message.',
      url: '/'
    };
  }

  const notificationOpts = {
    title: pushData.title || 'PWA Notification',
    body: pushData.body || '',
    icon: '/icons/icon-192.png',
    badge: '/icons/badge.png',
    data: { url: pushData.url || '/' }
  };

  event.waitUntil(
    self.registration.showNotification(notificationOpts.title, notificationOpts)
  );
});

// ==== Notification Click Action ====
self.addEventListener('notificationclick', event => {
  event.notification.close();

  const targetUrl = event.notification.data.url;
  event.waitUntil(
    clients.openWindow(targetUrl)
  );
});
```

