```js
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.6.0/workbox-sw.js');

if (self.Workbox) {
  console.log('Workbox loaded');
} else {
  console.error('Workbox not loaded');
}

/* ---------- Push subscription ---------- */
async function subscribeToPush() {
  const registration = await self.registration;
  const applicationServerKey = urlBase64ToUint8Array(
    'YOUR_VAPID_PUBLIC_KEY' // Replace with actual VAPID public key
  );

  try {
    const subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey,
    });
    // Send subscription to your backend to trigger push messages
    // fetch('/api/subscribe', {method: 'POST', body: JSON.stringify(subscription)});
  } catch (err) {
    console.error('Push subscription failed', err);
  }
}

function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(base64);
  const output = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) output[i] = raw.charCodeAt(i);
  return output;
}

/* ---------- Service Worker lifecycle ---------- */
self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open('dynamic-cache').then((cache) => {
      return cache.addAll([
        '/',
        '/index.html',
        '/styles.css',
        '/app.js',
        '/icons/icon-192.png',
        '/icons/icon-512.png',
      ]);
    })
  );
});

self.addEventListener('activate', (event) => {
  const allowedCaches = ['dynamic-cache', 'static-cache'];
  event.waitUntil(
    caches.keys().then((keys) =>
      Promise.all(
        keys.map((key) => {
          if (!allowedCaches.includes(key)) {
            return caches.delete(key);
          }
        })
      )
    )
  );
  self.clients.claim();
});

/* ---------- Fetch handling (dynamic cache) ---------- */
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  const url = new URL(event.request.url);

  // Static assets – cache first
  if (url.pathname.endsWith('.png') ||
      url.pathname.endsWith('.jpg') ||
      url.pathname.endsWith('.svg') ||
      url.pathname.endsWith('.css') ||
      url.pathname.endsWith('.js') ||
      url.pathname === '/') {
    event.respondWith(
      caches.match(event.request).then((cached) => cached || fetch(event.request))
    );
    return;
  }

  // Dynamic requests – network first, fallback to cache
  event.respondWith(
    (async () => {
      try {
        const networkResponse = await fetch(event.request);
        const cache = await caches.open('dynamic-cache');
        cache.put(event.request, networkResponse.clone());
        return networkResponse;
      } catch (err) {
        try {
          const cached = await caches.match(event.request);
          return cached || new Response('Offline', { status: 500 });
        } catch (e) {
          return new Response('Network error', { status: 500 });
        }
      }
    })()
  );
});

/* ---------- Push handling ---------- */
self.addEventListener('push', (event) => {
  const data = event.data?.json() ?? {};
  const title = data.title || 'Notification';
  const options = {
    body: data.body || '',
    icon: '/icons/icon-192.png',
    badge: '/icons/badge.png',
    data: data.payload || {}
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

/* ---------- Notification click ---------- */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = event.notification.data?.url || '/';
  event.waitUntil(
    clients.matchAll().then((clients) => {
      for (const client of clients) {
        if (client.url === target && 'focus' in client) {
          return client.focus();
        }
      }
      if (clients.openWindow) {
        return clients.openWindow(target);
      }
    })
  );
});

/* ---------- Periodic sync (optional) ---------- */
// If you want background sync for failed push or other requests, uncomment:
// self.addEventListener('sync', (event) => {
//   if (event.tag === 'push-sync') {
//     event.waitUntil(doSomething());
//   }
// });

/* ---------- Background sync example (optional) ---------- */
async function doSomething() {
  // Example: fetch a pending request
  const response = await fetch('/api/pending', { method: 'GET' });
  // Process response as needed
}
