**Node.js script – HTML / JSON → PDF (with advanced formatting & tables)**  

```js
/**
 * convert.js
 *
 * Usage:
 *   node convert.js input.html  output.pdf   # HTML → PDF
 *   node convert.js input.json  output.pdf   # JSON → PDF (table)
 *
 * Dependencies (install first):
 *   npm i puppeteer pdfmake
 *
 * The script detects the input type from the file extension:
 *   • .html / .htm  → rendered with headless Chrome (Puppeteer) → PDF.
 *   • .json         → parsed, turned into a PdfMake table and saved as PDF.
 *
 * Features demonstrated:
 *   • Loading local HTML and applying CSS (you can embed a <style> block or
 *     reference an external stylesheet – the script injects a minimal style
 *     block to guarantee a decent look).
 *   • Advanced PDF rendering (fonts, margins, page size) with Puppeteer.
 *   • Building a structured table from JSON data using PdfMake (including
 *     column definitions, alignment, and optional header styling).
 *   • Simple CLI handling and graceful error reporting.
 */

const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
const PdfMaker = require('pdfmake');

// ---------------------------------------------------------------------------
// Helper – read file & return string (UTF‑8)
function readFileUtf8(filePath) {
  return fs.readFileSync(filePath, { encoding: 'utf8' });
}

// ---------------------------------------------------------------------------
// 1️⃣ HTML → PDF (via Puppeteer)
async function htmlToPdf(htmlPath, pdfPath) {
  const html = readFileUtf8(htmlPath);

  // Minimal CSS to make the page look decent when printed.
  const css = `
    @page { size: A4; margin: 1cm; }
    body { font-family: "Helvetica", "Arial", sans-serif; line-height: 1.4; }
    h1, h2, h3 { color: #2c3e50; }
    table { width: 100%; border-collapse: collapse; margin-top: 1em; }
    th, td { border: 1px solid #ddd; padding: 0.4em; text-align: left; }
    th { background-color: #f2f2f2; }
  `;

  // Launch headless Chrome, inject the HTML + CSS, then export PDF.
  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();

  // Use a "data URL" to avoid any external file dependency.
  const dataUrl = `data:text/html;charset=utf-8,${encodeURIComponent(
    html + `<style>${css}</style>`
  )}`;

  await page.goto(dataUrl, { waitUntil: 'networkidle0' });

  // Generate PDF – you can tweak options (format, printBackground, etc.)
  await page.pdf({
    path: pdfPath,
    format: 'A4',
    printBackground: true,
    margin: { top: '1cm', right: '1cm', bottom: '1cm', left: '1cm' },
  });

  await browser.close();
  console.log(`✅  HTML → PDF saved to ${pdfPath}`);
}

// ---------------------------------------------------------------------------
// 2️⃣ JSON → PDF (via PdfMake – table‑centric)
function jsonToPdf(jsonPath, pdfPath) {
  const raw = readFileUtf8(jsonPath);
  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    console.error('❌  Failed to parse JSON:', e.message);
    process.exit(1);
  }

  // Expect an array of objects (rows). If the JSON is a single object,
  // wrap it in an array for a one‑row table.
  const rows = Array.isArray(data) ? data : [data];

  // Build column definitions automatically from the keys of the first row.
  const cols = Object.keys(rows[0] || {}).map((key) => ({
    title: key,
    width: 'auto',
  }));

  // PdfMake document definition.
  const docDefinition = {
    pageSize: 'A4',
    margins: [40, 60, 40, 40], // top, right, bottom, left (mm)
    content: [
      {
        text: 'Relatório gerado a partir de JSON',
        style: 'title',
        alignment: 'center',
        margin: [0, 0, 20, 0],
      },
      {
        text: `Gerado em: ${new Date().toLocaleString()}`,
        style: 'date',
        alignment: 'right',
        margin: [0, 0, 30, 0],
      },
      {
        table: {
          headerRows: 1,
          widths: cols.map((c) => (c.width === 'auto' ? 'auto' : c.width)),
          // Header style
          headerRowStyle: {
            fillColor: '#2c3e50',
            color: '#ffffff',
          },
          // Body rows
          body: rows.map((row) => {
            const rowData = cols.map((col) => row[col] ?? '');
            return [rowData];
          }),
          // Column definitions (title + optional width)
          columns: cols.map((col) => ({
            ...col,
            // You can add more properties here (e.g., hidden, pliable, etc.)
          })),
          // Optional column alignment (left, center, right)
          columnWidths: cols.map((c) => (c.title === 'ID' ? 60 : 'auto')),
          // Cell style
          cellStyle: {
            // You could add background colors per column, etc.
          },
        },
      },
    ],
    styles: {
      title: {
        fontSize: 22,
        bold: true,
        margin: [0, 0, 10, 0],
        alignment: 'center',
      },
      date: {
        fontSize: 12,
        color: '#777',
        alignment: 'right',
      },
    },
  };

  // Create the PDF and pipe it to a file.
  const pdfDoc = PdfMaker.createPdf(docDefinition);
  const stream = pdfDoc.pipe(fs.createWriteStream(pdfPath));

  // Wait for the stream to finish.
  stream.on('finish', () => {
    console.log(`✅  JSON → PDF saved to ${pdfPath}`);
  });

  stream.on('error', (err) => {
    console.error('❌  Error while writing PDF:', err);
    process.exit(1);
  });
}

// ---------------------------------------------------------------------------
// CLI handling
(async () => {
  const [, , inputPath, outputPath, type] = process.argv;

  if (!inputPath || !outputPath) {
    console.error('Usage: node convert.js <input.html|input.json> <output.pdf> [html|json]');
    process.exit(1);
  }

  const ext = path.extname(inputPath).toLowerCase();
  const inputType = type?.toLowerCase() ?? ext.slice(1); // fallback to file extension

  try {
    if (inputType === 'html' || ext === '.html' || ext === '.htm') {
      await htmlToPdf(inputPath, outputPath);
    } else if (inputType === 'json') {
      jsonToPdf(inputPath, outputPath);
    } else {
      console.error(`❌  Unsupported input type: "${inputType}". Use .html/.htm or .json`);
      process.exit(1);
    }
  } catch (err) {
    console.error('❌  Unexpected error:', err);
    process.exit(1);
  }
})();
```

### Como usar

1. **Instale as dependências**

   ```bash
   npm init -y               # (se ainda não houver package.json)
   npm i puppeteer pdfmake
   ```

   > *Puppeteer* baixará o Chromium na primeira execução – pode levar alguns minutos.

2. **Salve o script acima** como `convert.js`.

3. **Execute**:

   - **HTML → PDF**

     ```bash
     node convert.js sample.html output.pdf
     ```

   - **JSON → PDF** (o JSON deve conter um array de objetos; cada objeto vira uma linha da tabela)

     ```bash
     node convert.js data.json report.pdf json
     ```

   O script criará o arquivo `output.pdf` no diretório corrente, contendo:
   - Para HTML: a página renderizada pelo Chrome, com a formatação CSS embutida.
   - Para JSON: uma tabela bem estruturada (cabeçalhos, alinhamento, largura automática) e uma capa simples.

### O que o script demonstra

| Recurso | Como é feito |
|---------|--------------|
| **Leitura de arquivos** | `fs.readFileSync` (UTF‑8) |
| **Detecção de tipo** | Pela extensão (`.html/.htm` ou `.json`) ou pelo argumento opcional `html|json` |
| **HTML → PDF** | *Puppeteer* abre uma página *in‑memory* (data‑URL) → `page.pdf()` com opções de margem, tamanho de página e fundo |
| **JSON → PDF** | `pdfmake` constrói um objeto **document definition** → `PdfMaker.createPdf()` → stream → `fs.writeFileSync` |
| **Formatação avançada** | CSS embutido para a impressão, estilos de título/data no PDF, cabeçalhos de tabela com cor de fundo |
| **CLI amigável** | Mensagens de erro claras, verificação de argumentos, tratamento de exceções |

Com esse script você tem um ponto de partida robusto para converter documentos HTML ou JSON em PDFs visualmente sofisticados, usando duas das bibliotecas mais poderosas do ecossistema Node.js. Boa codificação!

