   - **JSON → PDF** (o JSON deve conter um array de objetos; cada objeto vira uma linha da tabela)

     ```bash
     node convert.js data.json report.pdf json
     ```

   O script criará o arquivo `output.pdf` no diretório corrente, contendo:
   - Para HTML: a página renderizada pelo Chrome, com a formatação CSS embutida.
   - Para JSON: uma tabela bem estruturada (cabeçalhos, alinhamento, largura automática) e uma capa simples.

### O que o script demonstra

| Recurso | Como é feito |
|---------|--------------|
| **Leitura de arquivos** | `fs.readFileSync` (UTF‑8) |
| **Detecção de tipo** | Pela extensão (`.html/.htm` ou `.json`) ou pelo argumento opcional `html|json` |
| **HTML → PDF** | *Puppeteer* abre uma página *in‑memory* (data‑URL) → `page.pdf()` com opções de margem, tamanho de página e fundo |
| **JSON → PDF** | `pdfmake` constrói um objeto **document definition** → `PdfMaker.createPdf()` → stream → `fs.writeFileSync` |
| **Formatação avançada** | CSS embutido para a impressão, estilos de título/data no PDF, cabeçalhos de tabela com cor de fundo |
| **CLI amigável** | Mensagens de erro claras, verificação de argumentos, tratamento de exceções |

Com esse script você tem um ponto de partida robusto para converter documentos HTML ou JSON em PDFs visualmente sofisticados, usando duas das bibliotecas mais poderosas do ecossistema Node.js. Boa codificação!

```javascript
#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

(async () => {
  const [, , inputFile, outputPdf] = process.argv;
  if (!inputFile || !outputPdf) {
    console.error('Usage: node convert.js <input.html|input.json> <output.pdf>');
    process.exit(1);
  }

  const ext = path.extname(inputFile).toLowerCase();
  let htmlContent;

  if (ext === '.json') {
    const jsonData = JSON.parse(fs.readFileSync(inputFile, 'utf8'));
    const tableRows = Object.entries(jsonData).map(([key, value]) => 
      `<tr><td>${key}</td><td>${JSON.stringify(value)}</td></tr>`
    );
    htmlContent = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <style>
          body { font-family: Arial, sans-serif; margin: 20px; }
          table { border-collapse: collapse; width: 100%; }
          td, th { border: 1px solid #000; padding: 8px; }
        </style>
      </head>
      <body>
        <h1>JSON converted to PDF</h1>
        <table>
          ${tableRows.join('')}
        </table>
      </body>
      </html>`;
  } else if (ext === '.html') {
    htmlContent = fs.readFileSync(inputFile, 'utf8');
  } else {
    console.error('Unsupported file type. Use .json or .html');
    process.exit(1);
  }

  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(htmlContent, { waitUntil: 'networkidle0' });
  await page.pdf({
    path: outputPdf,
    format: 'A4',
    printBackground: true,
  });
  await browser.close();
})();
```

```javascript
#!/usr/bin/env node
const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');
const ejs = require('ejs');

// Load an EJS template from file
function loadTemplate(filePath) {
  return fs.readFileSync(filePath, 'utf8');
}

// Convert JSON data to an HTML string using a simple table layout
function jsonToHtml(jsonData) {
  const html = `
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="utf-8">
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        table { border-collapse: collapse; width: 100%; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f2f2f2; }
      </style>
    </head>
    <body>
      <h1>Generated PDF</h1>
      <table>
        <tr><th>Property</th><th>Value</th></tr>
        ${Object.entries(jsonData)
          .map(([key, value]) => `<tr><td>${key}</td><td>${JSON.stringify(value)}</td></tr>`)
          .join('\n')}
      </table>
    </body>
    </html>`;
  return html;
}

// Main execution
(async () => {
  const [, , htmlFilePath, jsonFilePath] = process.argv;
  if (!htmlFilePath || !jsonFilePath) {
    console.error('Usage: node script.js <html-template-file> <json-data-file>');
    process.exit(1);
  }

  const templateSource = loadTemplate(htmlFilePath);
  const jsonData = JSON.parse(fs.readFileSync(jsonFilePath, 'utf8'));

  // Render the final HTML by inserting JSON data into the template
  const renderedHtml = ejs.render(templateSource, { data: jsonData });

  // Launch headless Chrome
  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();

  // Load the rendered HTML and generate PDF
  await page.setContent(renderedHtml, { waitUntil: 'networkidle0' });
  await page.pdf({
    path: 'output.pdf',
    format: 'A4',
    printBackground: true,
    margin: { top: '20px', right: '20px', bottom: '20px', left: '20px' },
  });

  await browser.close();
  console.log('PDF generated as output.pdf');
})();
```

