```javascript
#!/usr/bin/env node
import { promises as fs } from 'fs';
import path from 'path';
import { program } from 'commander';
import puppeteer from 'puppeteer';

program
  .requiredOption('-i, --input <file>', 'Input HTML or JSON file')
  .requiredOption('-o, --output <file>', 'Output PDF file')
  .option('-t, --type <type>', 'Input type: html or json', 'html')
  .parse();

const opts = program.opts();
const inputFile = path.resolve(opts.input);
const outputFile = path.resolve(opts.output);
const inputType = opts.type ?? 'html';

async function main() {
  let html;

  if (inputType === 'html') {
    html = await fs.readFile(inputFile, 'utf8');
  } else {
    const json = JSON.parse(await fs.readFile(inputFile, 'utf8'));
    html = await jsonToHtml(json);
  }

  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });

  await page.pdf({
    path: outputFile,
    format: 'A4',
    printBackground: true,
    margin: { top: '20px', right: '20px', bottom: '20px', left: '20px' },
  });

  await browser.close();
  console.log(`PDF created at ${outputFile}`);
}

function jsonToHtml(data) {
  if (!Array.isArray(data)) return '<p>Unsupported JSON structure</p>';

  const headers = Object.keys(data[0] || {});
  const thead = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
  const tbody = data
    .map(row => `<tr>${headers.map(h => `<td>${row[h]}</td>`).join('')}</tr>`)
    .join('');
  return `<h1>JSON Converted to PDF</h1><table>${thead}${tbody}</table>`;
}

main().catch(err => {
  console.error('Conversion failed:', err);
  process.exit(1);
});
```

